(() => {
'use strict';
const M=RiskSheet,$=s=>document.querySelector(s),KEY='ann-risk-sheet-v2';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let rows=M.seed(),asOf='2026-01-08',threshold=3,active={rowId:rows[0].id,col:0},sheet='main',memberRow=null;
let undo=[],redo=[],storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.rows)&&saved.rows.length&&saved.rows.every(M.isRow)){rows=saved.rows;active.rowId=rows[0].id;if(/^\d{4}-\d{2}-\d{2}$/.test(saved.asOf))asOf=saved.asOf;if(Number.isInteger(saved.threshold)&&saved.threshold>0)threshold=saved.threshold;}}catch{storageOK=false;}
const snapshot=()=>JSON.stringify({rows,asOf,threshold});
function record(){undo.push(snapshot());if(undo.length>50)undo.shift();redo=[];}
function notify(message){$('#message').textContent=message;}
function save(message){try{localStorage.setItem(KEY,snapshot());storageOK=true;}catch{storageOK=false;}$('#save-state').textContent=storageOK?'已儲存於此瀏覽器 · 示意資料':'暫存模式 · 關閉頁面後不保留';$('#undo').disabled=!undo.length;$('#redo').disabled=!redo.length;if(message)notify(message);}
function restore(value){const state=JSON.parse(value);rows=state.rows;asOf=state.asOf;threshold=state.threshold;$('#as-of').value=asOf;$('#revision-threshold').value=threshold;if(!rows.some(r=>r.id===active.rowId))active.rowId=rows[0].id;renderRows();renderQuery();save('已還原儲存格資料。');}
function membersMarkup(row){return `<button class="member-cell" data-members="${escape(row.id)}" aria-label="${escape(row.code||'新案件')} 組員">${row.members.length?row.members.map(n=>`<span>${escape(n)}</span>`).join(''):'<span class="member-empty">選擇組員</span>'}<em>⌄</em></button>`;}
function control(row,col,index){
 const value=M.cellValue(row,col,asOf,threshold),label=`${row.code||'新案件'} ${col.label}`;
 if(col.type==='gap')return '';
 if(col.type==='computed')return `<div class="computed" tabindex="0" aria-label="${escape(label)}，自動計算">${M.risk(row,asOf,threshold).messages.map(t=>`<span>${escape(t)}</span>`).join('')}</div>`;
 if(col.type==='members')return membersMarkup(row);
 if(col.type==='owner'||col.type==='status'){const options=col.type==='owner'?[...new Set(['',...M.people,value])]:M.statuses;return `<select class="cell" aria-label="${escape(label)}">${options.map(v=>`<option value="${escape(v)}"${value===v?' selected':''}>${escape(v||'選擇負責人')}</option>`).join('')}</select>`;}
 return `<input class="cell" type="${col.type==='number'?'number':col.type==='date'?'date':'text'}"${col.type==='number'?' min="0" step="1"':''} value="${escape(value)}" aria-label="${escape(label)}"${col.type==='text'?' maxlength="500"':''}>`;
}
function renderHead(){
 $('#sheet-cols').innerHTML='<col style="width:46px">'+M.columns.map(c=>`<col style="width:${c.width}px">`).join('');
 $('#sheet-table').style.width=(46+M.columns.reduce((a,c)=>a+c.width,0))+'px';
 $('#sheet-head').innerHTML='<tr class="letters"><th></th>'+M.columns.map(c=>`<th scope="col">${c.letter}</th>`).join('')+'</tr><tr class="group-row"><th></th><th colspan="6" class="group-owner">專案負責人</th><th class="gap"></th><th colspan="2" class="group-client">客戶互動資料</th><th class="gap"></th><th colspan="5" class="group-schedule">內部時程控管</th></tr><tr class="label-row"><th class="row-number">1</th>'+M.columns.map(c=>`<th scope="col" class="${c.type==='gap'?'gap':''}">${escape(c.label)}</th>`).join('')+'</tr>';
}
function filtered(){const search=$('#search').value.trim().toLowerCase();return rows.filter(r=>!search||M.columns.some(c=>M.cellValue(r,c,asOf,threshold).toLowerCase().includes(search)));}
function renderRows(){const shown=filtered();$('#sheet-body').innerHTML=shown.map(row=>{const index=rows.indexOf(row);return `<tr data-row="${escape(row.id)}"><th scope="row" class="row-number">${index+2}</th>`+M.columns.map((c,i)=>`<td data-col="${i}" class="${c.type==='gap'?'gap':''}">${control(row,c,i)}</td>`).join('')+'</tr>';}).join('')||'<tr><td colspan="16" class="empty-row">沒有符合條件的案件。清除搜尋可回到完整表格。</td></tr>';refreshCells();syncFormula();}
function refreshCells(){
 const stateClass={'執行中':'state-active','結案':'state-closed','等客戶':'state-waiting','暫停':'state-paused','待審核':'state-review'};
 $('#sheet-body').querySelectorAll('tr[data-row]').forEach(tr=>{const row=rows.find(r=>r.id===tr.dataset.row),flags=M.risk(row,asOf,threshold);tr.querySelectorAll('td[data-col]').forEach(td=>{const col=M.columns[Number(td.dataset.col)];td.className=col.type==='gap'?'gap':flags.cells[col.letter]||'';if(col.key==='status')td.classList.add(stateClass[row.status]);if(col.type==='computed')td.querySelector('.computed').innerHTML=flags.messages.map(t=>`<span>${escape(t)}</span>`).join('');});});
 $('#sheet-summary').textContent=sheet==='main'?`顯示 ${filtered().length} / ${rows.length} 列 · A–O 欄`:'';
}
function renderQuery(){const selected=$('#query-person').value||'Ann';const names=[...new Set([...M.people,...rows.flatMap(r=>[r.owner,...r.members]).filter(Boolean)])];$('#query-person').innerHTML=names.map(n=>`<option${n===selected?' selected':''}>${escape(n)}</option>`).join('');const matches=M.query(rows,$('#query-person').value,$('#query-status').value);$('#query-results').innerHTML=matches.map((r,i)=>`<tr><th class="row-number" scope="row">${i+4}</th><td>${escape(r.code)}</td><td>${escape(r.owner)}</td><td>${escape(r.members.join(', '))}</td><td><span class="query-status-pill">${escape(r.status)}</span></td><td>${i===0?matches.length:''}</td></tr>`).join('')||'<tr><th class="row-number">4</th><td colspan="4">沒有符合條件的案件。</td><td>0</td></tr>';if(sheet==='query')$('#sheet-summary').textContent=`符合 ${matches.length} 件 · A–E 欄`;}
function syncFormula(){const row=rows.find(r=>r.id===active.rowId);if(!row)return;const col=M.columns[active.col];$('#cell-address').textContent=col.letter+(rows.indexOf(row)+2);$('#formula-input').value=M.cellValue(row,col,asOf,threshold);$('#formula-input').readOnly=!col.key||sheet!=='main';$('#cell-hint').textContent=col.type==='computed'?'自動計算的風險提示':'Enter 套用儲存格內容';}
function cellContext(target){const td=target.closest('td[data-col]'),tr=td?.closest('tr[data-row]');if(!td||!tr)return null;return{rowId:tr.dataset.row,col:Number(td.dataset.col)};}
function commit(rowId,col,value){const index=rows.findIndex(r=>r.id===rowId);if(index<0)return;try{const next=structuredClone(rows);M.setCell(next,index,col,value,asOf);if(JSON.stringify(next)===JSON.stringify(rows))return;record();rows=next;refreshCells();renderQuery();syncFormula();save('已更新 '+M.columns[col].letter+(index+2)+'，預警與案量已同步。');}catch(e){notify(e.message);renderRows();}}
function selectSheet(value){sheet=value;$('#main-sheet').hidden=value!=='main';$('#query-sheet').hidden=value!=='query';document.querySelectorAll('[data-sheet]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.sheet===value)));if(value==='query'){renderQuery();$('#cell-address').textContent='A2';$('#formula-input').value=$('#query-person').value;$('#formula-input').readOnly=true;$('#cell-hint').textContent='查詢結果由主表即時更新';}else{refreshCells();syncFormula();}}
$('#sheet-body').addEventListener('focusin',e=>{const context=cellContext(e.target);if(context){active=context;syncFormula();}});
$('#sheet-body').addEventListener('change',e=>{if(!e.target.matches('input.cell,select.cell'))return;const context=cellContext(e.target);if(context)commit(context.rowId,context.col,e.target.value);});
$('#formula-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.target.readOnly){e.preventDefault();commit(active.rowId,active.col,e.target.value);renderRows();}});
$('#sheet-body').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('input.cell,select.cell')){e.preventDefault();const context=cellContext(e.target);commit(context.rowId,context.col,e.target.value);const visible=[...$('#sheet-body').querySelectorAll('tr[data-row]')],idx=visible.findIndex(tr=>tr.dataset.row===context.rowId);visible[idx+(e.shiftKey?-1:1)]?.querySelector(`td[data-col="${context.col}"] input,td[data-col="${context.col}"] select,td[data-col="${context.col}"] button`)?.focus();}});
$('#sheet-body').addEventListener('paste',e=>{const text=e.clipboardData?.getData('text/plain');if(!text||!/[\t\n]/.test(text))return;const context=cellContext(e.target);if(!context)return;e.preventDefault();try{const next=structuredClone(rows),start=rows.findIndex(r=>r.id===context.rowId),matrix=text.replace(/\r/g,'').replace(/\n$/,'').split('\n').map(r=>r.split('\t'));matrix.forEach((values,offset)=>{if(!next[start+offset])next.push(M.blank('pasted-'+Date.now()+'-'+offset));values.forEach((value,columnOffset)=>{const column=context.col+columnOffset;if(column<M.columns.length)M.setCell(next,start+offset,column,value,asOf);});});record();rows=next;renderRows();renderQuery();save('已貼上多格資料；G、J 分隔欄與 M 預警欄保持自動。');}catch(error){notify('未套用貼上內容：'+error.message);}});
$('#sheet-body').addEventListener('click',e=>{const btn=e.target.closest('[data-members]');if(!btn)return;memberRow=btn.dataset.members;const r=rows.find(r=>r.id===memberRow);$('#member-options').innerHTML=M.people.map(name=>`<label><input type="checkbox" value="${escape(name)}"${r.members.includes(name)?' checked':''}>${escape(name)}</label>`).join('');$('#extra-members').value=r.members.filter(n=>!M.people.includes(n)).join(', ');$('#member-dialog').showModal();});
$('#member-form').addEventListener('submit',e=>{e.preventDefault();const values=[...$('#member-options').querySelectorAll('input:checked')].map(e=>e.value);values.push(...$('#extra-members').value.split(/[,，、]/));commit(memberRow,2,values.join(','));$('#member-dialog').close();renderRows();});
$('#cancel-members').addEventListener('click',()=>$('#member-dialog').close());
$('#search').addEventListener('input',renderRows);
$('#add-row').addEventListener('click',()=>{record();const row=M.blank('row-'+Date.now());rows.push(row);$('#search').value='';active={rowId:row.id,col:0};selectSheet('main');renderRows();renderQuery();save('已新增一列，欄位順序與原表一致。');$('#sheet-body').lastElementChild?.querySelector('input')?.focus();});
$('#as-of').addEventListener('change',()=>{const next=$('#as-of').value;if(!next){$('#as-of').value=asOf;return;}record();asOf=next;refreshCells();renderQuery();syncFormula();save('已依基準日重新計算預警。');});
$('#revision-threshold').addEventListener('change',()=>{const next=Number($('#revision-threshold').value);if(!Number.isInteger(next)||next<1){$('#revision-threshold').value=threshold;return;}record();threshold=next;refreshCells();renderQuery();syncFormula();save('已更新修改次數提醒門檻。');});
$('#undo').addEventListener('click',()=>{if(!undo.length)return;redo.push(snapshot());restore(undo.pop());});
$('#redo').addEventListener('click',()=>{if(!redo.length)return;undo.push(snapshot());restore(redo.pop());});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'&&!document.querySelector('dialog[open]')){e.preventDefault();$(e.shiftKey?'#redo':'#undo').click();}});
$('#reset').addEventListener('click',()=>{if(!confirm('還原原圖的 12 筆示例資料？這一步可使用「復原」撤回。'))return;record();rows=M.seed();asOf='2026-01-08';threshold=3;$('#as-of').value=asOf;$('#revision-threshold').value=threshold;$('#search').value='';active={rowId:rows[0].id,col:0};renderRows();renderQuery();save('已還原原圖示例資料。');});
document.querySelectorAll('[data-sheet]').forEach(b=>b.addEventListener('click',()=>selectSheet(b.dataset.sheet)));
$('#query-person').addEventListener('change',()=>{renderQuery();$('#formula-input').value=$('#query-person').value;});$('#query-status').addEventListener('change',renderQuery);
$('#show-rules').addEventListener('click',()=>$('#rules-dialog').showModal());$('#close-rules').addEventListener('click',()=>$('#rules-dialog').close());
$('#as-of').value=asOf;$('#revision-threshold').value=threshold;$('#query-status').innerHTML='<option value="">全部狀態</option>'+M.statuses.map(s=>`<option>${s}</option>`).join('');renderHead();renderRows();renderQuery();if(!storageOK)$('#save-state').textContent='暫存模式 · 關閉頁面後不保留';if(location.hash==='#capacity')selectSheet('query');
})();
